using UnityEngine;

namespace Echo.Game.Seasons
{
    /// <summary>
    /// A season's look (seasons doc, "Season themes"): every field is optional and falls back to the normal art.
    /// Looks only: nothing here reaches the simulation, and reskinned hazards keep the original's outline and size
    /// (SeasonArtTests). Generated by Editor/SeasonThemes with the art in Editor/Art/PixelSeasons.
    /// </summary>
    [CreateAssetMenu(menuName = "Echo/Season Theme")]
    public sealed class SeasonTheme : ScriptableObject
    {
        [Tooltip("Matches the schedule's id (SeasonIds).")]
        public string Id = "";
        public string Title = "";

        [Header("Background and palette")]
        [Tooltip("Sky colours by distance, like a palette cosmetic (500 m a stop). Empty keeps the player's palette.")]
        public Color[] PaletteStops = new Color[0];
        [Range(0f, 1f)] public float PaletteBlend = 1f;
        [Tooltip("Replaces the far mountains.")]
        public Sprite FarLayer;
        [Tooltip("Replaces the Graveyard hills.")]
        public Sprite NearLayer;

        [Header("Background effects layer (behind the floor and everything on it)")]
        public SeasonEffect Effect;
        public Sprite[] EffectSprites = new Sprite[0];
        [Tooltip("Each sprite drawn in turn in these colours; empty draws them as they are.")]
        public Color[] EffectColours = new Color[0];
        [Range(0, Views.SeasonEffectsView.MaxParticles)] public int EffectCount = 40;
        [Tooltip("Units a second.")]
        public float EffectFall = 1.2f;
        [Tooltip("Units either side.")]
        public float EffectSway = 0.3f;
        [Tooltip("How far the layer drifts back as the camera moves (0 fixed to the screen, 1 fixed to the world).")]
        [Range(0f, 1f)] public float EffectParallax = 0.3f;

        [Header("Fireworks (also behind the floor): bursts high in the sky")]
        public bool Fireworks;
        public Sprite FireworkSpark;
        public Color[] FireworkColours = new Color[0];
        [Tooltip("Bursts a minute normally.")]
        public float FireworksPerMinute = 6f;
        [Tooltip("Seasons doc (New Year): when the Daily Haunt board resets at 00:00 UTC, a show this long, ten times as busy.")]
        public float ResetShowSeconds;
        [Tooltip("The toast as the show starts, e.g. HAPPY NEW YEAR!")]
        public string ResetShowToast = "";

        [Header("Obstacles: same size and outline as the originals, greyscale, tinted as hazards")]
        public Sprite Spike;
        public Sprite Block;
        [Tooltip("The floor's top edge (snow on the ground).")]
        public Sprite GroundTop;

        [Header("Graves")]
        [Tooltip("The world grave, 12 x 16 like the original.")]
        public Sprite Grave;
        [Tooltip("Drawn in its own colours, not tinted like stone.")]
        public bool GraveInColour;
        [Tooltip("The death screen's large headstone, 56 x 60 with the same plain face for the epitaph.")]
        public Sprite Headstone;

        [Header("Ghosts")]
        [Tooltip("Worn by every ghost but the Nemesis, at the top of its head (the sprite's pivot places it).")]
        public Sprite GhostAccessory;
        [Tooltip("Worn by the Nemesis instead of its horns.")]
        public Sprite NemesisAccessory;

        [Header("Death screen")]
        public string DeathLine = "";
        [Tooltip("Only when the Nemesis ended the run.")]
        public bool DeathLineNemesisOnly;

        [Header("Music")]
        [Tooltip("Played once over the music when the season first shows in a session (optional).")]
        public AudioClip Stinger;
    }
}
